struct DefaultCompare {
    bool operator()(int a, int b) const { return a < b; }
};

// Functor Type (Op) is a Template Parameter
// Default Type (DefaultCompare) and Default Object ({}) provided
template <typename Op = DefaultCompare>
int process(int a, int b, Op op = {}) {
    if (op(a, b)) {
        return b;
    }
    return a;
}

// Custom Functor for compile-time specialization
struct GreaterThan {
    bool operator()(int a, int b) const { return a > b; }
};

// Usage:
// int max_val = process(10, 5);          // Uses DefaultCompare (a < b)
// int min_val = process<GreaterThan>(10, 5); // Uses GreaterThan (a > b)
